import numpy as np
from scipy import ndimage as ndi
from PIL import Image

def lab(rgb):
 a=rgb.astype(float)/255
 a=np.where(a<=.04045,a/12.92,((a+.055)/1.055)**2.4)
 xyz=a@np.array([[.4124564,.3575761,.1804375],[.2126729,.7151522,.0721750],[.0193339,.1191920,.9503041]]).T
 xyz/=np.array([.95047,1,1.08883])
 f=np.where(xyz>.008856,xyz**(1/3),7.787*xyz+16/116)
 return np.stack([116*f[:,:,1]-16,500*(f[:,:,0]-f[:,:,1]),200*(f[:,:,1]-f[:,:,2])],axis=-1)

def compare(a,b,sigma=4.507):
 aa=ndi.gaussian_filter(a.astype(float),(sigma,sigma,0));bb=ndi.gaussian_filter(b.astype(float),(sigma,sigma,0))
 la=lab(aa);lb=lab(bb);de=np.linalg.norm(la-lb,axis=-1)
 return np.mean(de),np.percentile(de,90)

